const prettifyJson = require("../util");
const cheerio = require("cheerio");

const formatCollaborators = (root, list) => {
  const newArr = [];
  list.each((i, el) => {
    const href = root(el).attr("href");
    const username = href.substr(2, href.length);
    newArr.push(username);
  });
  return newArr;
};

const formatDetails = (root, list) => {
  const result = {};
  const labels = [
    "Version",
    "License",
    "Unpacked Size",
    "Total Files",
    "Last publish"
  ];
  list.each((index, el) => {
    result[labels[index]] = root(el).text();
  });
  return result;
};

const formatHyperLinks = (root, list) => {
  const result = {};
  const labels = ["Homepage", "Repository"];
  list.each((index, el) => {
    result[labels[index]] = root(el).attr("href");
  });
  return result;
};

module.exports = body => {
  const $ = cheerio.load(body);

  const title = $("span._50685029").attr("title");
  const description = $("p.package-description-redundant").text();
  const collaborators = $("div.fdbf4038 li._426b8533 a");
  const contents = $("p.f2874b88");
  const repo = $("a.b2812e30");

  const titleData = {
    Title: title,
    Description: description
  };

  //merge objects
  const result = {
    ...titleData,
    ...formatDetails($, contents),
    ...formatHyperLinks($, repo),
    Collaborators: formatCollaborators($, collaborators)
  };

  return prettifyJson(result);
};

