const prettifyJson = require("../util");
const cheerio = require("cheerio");

/**
 * Get the social links related to the profile
 */
const parseList = ($, links) => {
  let arr = [];
  links.each((i, el) => {
    arr.push($(el).attr("href"));
  });
  return arr;
};

/**
 * Get all the published packages of the author
 * along with all the related details like
 * description,version,last-update etc.
 */
const getPackageInfo = ($, list) => {
  let arr = [];
  list.each((i, el) => {
    const title = $(el)
      .find("a h3.db7ee1ac")
      .text();

    const description = $(el)
      .find("p._8fbbd57d")
      .text();

    const version = $(el)
      .find("div._0be7a12f span._66c2abad")
      .text()
      .split("•")[0]
      .split(" ")[1];

    const url = "https://npmjs.com";
    const link = $(el)
      .find("a")
      .attr("href");

    const last_update = $(el)
      .find("div._0be7a12f span._66c2abad")
      .text()
      .split("•")[1]
      .trim();

    arr.push({
      title: title,
      description: description,
      version: version,
      link: url + link,
      last_update: last_update
    });
  });
  return arr;
};

module.exports = body => {
  const $ = cheerio.load(body);

  // Parent_Profile_Root :
  const parent = $("div._73a8e6f0");

  const avatar_url = parent.find("img").attr("src");
  const user_name = parent.find("h2.b219ea1a").text();
  const profile_name = parent.find("div.black-50").text();
  // social links array
  const social_links = parent.find("ul._07eda527 li a");

  // Parent_Packages_Root
  const package_root = $("div.d2f60d44");

  const num_package = package_root
    .find("ul.cfb2a888")
    .find("li._8055e658 a._38ce9a85 span span")
    .html();

  const num_org = package_root
    .find("ul.cfb2a888")
    .find("li._2a0881eb a._38ce9a85 span span")
    .html();

  const package_list = package_root.find(
    "div div._0897331b section.ef4d7c63 div.w-80"
  );

  const result = {
    user_name: user_name,
    profile_name: profile_name,
    avatar_url: avatar_url,
    social_links: parseList($, social_links),
    num_packages: num_package,
